using System;
using System.Collections.Generic;

namespace Libraries.DNV.Logging
{
    /// <summary>
    /// Which subsystem a log line belongs to — severity is already the method (Info/Warning/Error).
    /// Library categories are the static fields below; a game declares its own in Project Settings > Logger
    /// (ids from <see cref="FirstGameId"/>), they are generated into AutoGenerated/GameLogCategories.cs.
    /// Ids are serialized in LoggerSettings.asset — never reuse or renumber them.
    /// </summary>
    public readonly struct LogCategory : IEquatable<LogCategory>
    {
        public const int FirstGameId = 100;

        /// <summary>Legacy catch-all kept for already migrated call sites. Prefer a concrete subsystem.</summary>
        public static readonly LogCategory Debug = new(0, nameof(Debug));

        /// <summary>Legacy severity-as-category kept for already migrated call sites. Prefer a concrete subsystem.</summary>
        public static readonly LogCategory Error = new(1, nameof(Error));

        public static readonly LogCategory Core = new(2, nameof(Core));
        public static readonly LogCategory Cms = new(3, nameof(Cms));
        public static readonly LogCategory DependencyInjection = new(4, nameof(DependencyInjection));
        public static readonly LogCategory Assets = new(5, nameof(Assets));
        public static readonly LogCategory Level = new(6, nameof(Level));
        public static readonly LogCategory Pool = new(7, nameof(Pool));
        public static readonly LogCategory State = new(8, nameof(State));
        public static readonly LogCategory Animation = new(9, nameof(Animation));
        public static readonly LogCategory Rendering = new(10, nameof(Rendering));
        public static readonly LogCategory Editor = new(11, nameof(Editor));
        public static readonly LogCategory Commands = new(12, nameof(Commands));

        public static IReadOnlyList<LogCategory> Library { get; } = new[]
        {
            Debug, Error, Core, Cms, DependencyInjection, Assets, Level, Pool, State, Animation, Rendering, Editor, Commands
        };

        public int Id { get; }
        public string Name { get; }

        public LogCategory(int id, string name)
        {
            Id = id;
            Name = name;
        }

        public bool Equals(LogCategory other) => Id == other.Id;
        public override bool Equals(object obj) => obj is LogCategory other && Equals(other);
        public override int GetHashCode() => Id;
        public override string ToString() => Name;

        public static bool operator ==(LogCategory left, LogCategory right) => left.Equals(right);
        public static bool operator !=(LogCategory left, LogCategory right) => !left.Equals(right);
    }
}
